.items { margin-top: 26px; border-top: 1px solid var(--ink); }
.item { display: grid; grid-template-columns: 72px 1fr auto; gap: 16px; padding: 14px 0; border-bottom: 1px solid var(--line); align-items: center; }
.item img { width: 72px; height: 90px; }
.item .ret { font-size: 10px; letter-spacing: .18em; text-transform: uppercase; color: var(--muted); }
.item .nm { font-family: var(--serif); font-size: 21px; line-height: 1.15; margin: 2px 0; }
.item .nm a:hover { color: var(--accent); }
.item .av { font-size: 12px; color: var(--done); }
.item .av.low { color: var(--working); }
.item .pr { text-align: right; font-size: 15px; font-weight: 500; }
.item .pr s { display: block; font-size: 12px; color: var(--muted); font-weight: 400; }
