def clipbook_query(terms: list[str], limit: int = 4) -> dict:
    t0 = time.perf_counter()
    try:
        clips = _clips()
        words = {w for t in terms for w in re.findall(r"[a-z]{3,}", t.lower()) if w not in STOP}

        def score(c):
            hay = ((c.get("description") or "") + " " + " ".join(c.get("hashtags") or [])).lower()
            return sum(w in hay for w in words)

        ranked = sorted(clips, key=lambda c: (-score(c), -(c.get("play_count") or 0)))
        picked = [c for c in ranked if score(c) >= 2][:limit]
        out = [{"text": (c.get("description") or "")[:160], "url": c["url"], "creator": c.get("profile_username"),
                "plays": c.get("play_count"), "tags": (c.get("hashtags") or [])[:4], "date": (c.get("create_time") or "")[:10]}
               for c in picked]
        return {"status": "CLIPBOOK", "searched": len(clips), "matched": len(out), "terms": sorted(words)[:12], "clips": out,
                "ms": int((time.perf_counter() - t0) * 1000)}
    except Exception as exc:
        print(f"[clipbook] FALLBACK: {exc!r}")
        return {"status": "FALLBACK", "searched": 0, "matched": 0, "clips": [], "error": str(exc)[:200]}

